<!DOCTYPE html>
<html>
<head>
    <title>Dark Mode Toggle</title>
    <style>
        body {
            background-color: #fff;
            color: #000;
        }
        #toggleButton {
            cursor: pointer;
        }
    </style>
</head>
<body>
    <button id="toggleButton">Toggle Dark Mode</button>

    <script>
        var isDarkMode = false;

        function toggleDarkMode() {
            isDarkMode = !isDarkMode;
            localStorage.setItem('isDarkMode', isDarkMode);

            var body = document.body;
            body.style.backgroundColor = isDarkMode ? '#333' : '#fff';
            body.style.color = isDarkMode ? '#fff' : '#000';
        }

        document.getElementById('toggleButton').addEventListener('click', toggleDarkMode);

        if (localStorage.getItem('isDarkMode')) {
            isDarkMode = true;
            toggleDarkMode();
        }
    </script>
</body>
</html>
